import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { PyRandom } from "../src/pyrandom.ts";

// Vectors generated by CPython: python3 -c "random.Random(seed)..." (see git history of this file)
const V = JSON.parse(readFileSync(new URL("./pyrandom.vectors.json", import.meta.url), "utf8"));

for (const [seed, v] of Object.entries<any>(V)) {
  test(`matches CPython for seed ${seed}`, () => {
    const r = new PyRandom(Number(seed));
    assert.deepEqual(Array.from({ length: 5 }, () => r.random()), v.random);
    assert.deepEqual(Array.from({ length: 10 }, () => r.randint(1, 6)), v.randint);
    assert.deepEqual(Array.from({ length: 5 }, () => r.randrange(3, 1000)), v.randrange);
    assert.deepEqual(Array.from({ length: 5 }, () => r.choice([..."abcdefg"])), v.choice);
    assert.deepEqual(r.shuffle(Array.from({ length: 20 }, (_, i) => i)), v.shuffle);
    assert.deepEqual(Array.from({ length: 8 }, () => r.choices([..."abcd"], [5, 3, 4, 0.5])), v.choices);
    assert.deepEqual(Array.from({ length: 5 }, () => r.choices([..."abcd"])), v.choicesU);
    assert.deepEqual([1, 7, 31, 32].map((k) => r.getrandbits(k)), v.bits);
  });
}

test("state round trip", () => {
  const a = new PyRandom(5);
  a.random();
  const b = new PyRandom(a.getState());
  assert.equal(a.randint(0, 1000), b.randint(0, 1000));
});
